import re, csv
records={}
for path, prefix in [('/app/input/original_instruction.md','OI'),('/app/input/clarification.md','CL')]:
    txt=open(path).read()
    for m in re.finditer(r'^## (OI-\d+|CL-\d+) `([^`]+)`\n(.*?)(?=\n## |\Z)', txt, re.M|re.S):
        eid, subject, body = m.groups()
        records[eid]=(subject, body.strip())
print('Record entries:')
for eid in sorted(records):
    print(eid, records[eid][0], '::', records[eid][1].replace('\n',' ')[:120])
print('\nRows with CL cited_entry for different subject (RP-407 candidates):')
rows=list(csv.DictReader(open('/app/input/letter_lines.csv', newline='')))
for r in rows:
    c=r['cited_entry']
    if c.startswith('CL-') and c in records and records[c][0] != r['subject']:
        print(r['line_id'], 'subject=', r['subject'], 'cited=', c, 'cited_subject=', records[c][0], 'position=', r['position'])
